// Generated by philote from page /books. Do not edit.
import type { Metadata } from "next";
import { connection } from "next/server";
import { Suspense } from "react";

import * as api from "@/lib/api";
import { must } from "@/lib/backend";
import { readBookShelf } from "@/lib/reads";

import BookShelf from "@/components/common/book-shelf";

export const metadata: Metadata = { title: "Books" };

export default function Page() {
    return (
        <main className="flex flex-1 flex-col">
            <Suspense fallback={<p className="px-4 py-16 text-center text-muted-foreground">Loading…</p>}>
                <Sections />
            </Suspense>
        </main>
    );
}

// Sections streams in after the page's shell.
async function Sections() {
    await connection();
    const loaded = await must(api.books.list());
    const props1 = await readBookShelf(loaded);
    return (
        <>
            {props1.books.length === 0 ? <p className="mx-auto w-full max-w-5xl px-4 py-16 text-center text-muted-foreground sm:px-6">{"No books yet."}</p> : <BookShelf {...props1} />}
        </>
    );
}
